import json,subprocess,time,urllib.request
rid='run_mvaxg8be_1099f77b3b';obs=[]
for i in range(5):
 try:
  with urllib.request.urlopen('http://127.0.0.1:8787/v1/inspect/'+rid,timeout=5) as r:o=json.load(r)
  d=o.get('durable') or {};c=d.get('workflow_cursor') or {}
