  s={'step':i+1,'job':d.get('job_status'),'generation':d.get('generation'),'cursor':c.get('step_id'),'phase':c.get('step_phase'),'role':e.get('role'),'invoke_phase':e.get('phase'),'elapsed_ms':e.get('elapsed_ms'),'failure_code':e.get('failure_code')}
