  if s['job'] in ('DONE','BLOCKED','FAILED','CANCELLED'):break
 except Exception as err:obs.append({'step':i+1,'error':type(err).__name__})
 if i<4:time.sleep(11)
body='DEBUGAI_SIX_ROLE_LIVE_STAGE_PROGRESS\n'+json.dumps({'run_id':rid,'observed_transitions':obs},ensure_ascii=False,indent=2)
p=subprocess.run(['gh','api','-X','POST','repos/seigo-gace/debug-ai/issues/41/comments','-f','body='+body],capture_output=True,text=True,timeout=26)
if p.returncode:raise SystemExit('GH_PROGRESS_POST_FAILED')
print('SIX_ROLE_STAGE_COMMENT='+json.loads(p.stdout)['html_url'])
PY
